def table(headers,data):
    esc=lambda x:str(x).replace('|','/').replace('\n',' ')
    return '\n\n|'+ '|'.join(headers)+'|\n|'+'|'.join('---' for _ in headers)+'|\n'+''.join('|'+ '|'.join(esc(v) for v in row)+'|\n' for row in data)+'\n'
